head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst06000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst06000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_paxreq", fn: function () { return String(String((dma_pageContext.get("paxreq") ?? ""))); } },
        { childId: "ipt_outsvcno", fn: function () { return String(String((dma_pageContext.get("outsvcno") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        if ($c.util.getComponent('ipt_paxreq').getValue() === "y") {
            (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(PAXNET)");
        } else {
            if ($c.util.getComponent('ipt_outsvcno').getValue() === "02") {
                (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(헤럴드미디어)");
            }
        }
        // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
        //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
        //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "2 ') */
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst06000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

