 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (scwin.checkDateValidation($c.util.getComponent('cal_fromDate'), $c.util.getComponent('cal_toDate')) === false) {
        return;
    }
    scwin.fnClearCheck();
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchStockIssueList");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
};

/**
 * @method
 * @name fnDetailViewEtf
 * @description fn Detail View Etf 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDetailViewEtf = async function (val) {
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $c.util.getComponent("dma_fnDownloadReq").set("bzProcsNo", val);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchEtfStockIssueDetail");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchEtfStockIssueDetail");
