 * @method
 * @name fnCloseDetail
 * @description fn Close Detail 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCloseDetail = function () {
    (($c.util.getComponent('detail')) && ($c.util.getComponent('detail')).removeAll ? ($c.util.getComponent('detail')).removeAll() : (($c.util.getComponent('detail')) && ($c.util.getComponent('detail')).setValue ? ($c.util.getComponent('detail')).setValue('') : void 0));
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
};

/**
 * @method
 * @name fnClearCheck
 * @description fn Clear Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnClearCheck = function () {
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "");
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    }
};

/**
 * @method
 * @name setCorpInfo2
 * @description set Corp Info2 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuCd ipt_repIsuCd
 * @param {String} repIsuKorNm repIsuKorNm
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} rd_marketType rd_marketType
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo2 = function (ipt_isurCd, kisComCd, ipt_repIsuCd, repIsuKorNm, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, rd_marketType) {
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", ipt_isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", ipt_repIsuCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuCd ipt_repIsuCd
 * @param {String} repIsuKorNm repIsuKorNm
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (ipt_isurCd, kisComCd, ipt_repIsuCd, repIsuKorNm, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", ipt_isurCd);
    $("#searchForm > #kisComCd").val(kisComCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", ipt_repIsuCd);
    $c.util.getComponent('AKCKwd').setValue(ipt_repIsuSrtCd);
};

/**
 * @method
 * @name fnSearchCorpBasicInfo
 * @description fn Search Corp Basic Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCorpBasicInfo = function () {
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSetCorpBasicInfo(items[0]);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSetCorpBasicInfo(null);
    }
}
};

/**
 * @method
 * @name fnSetCorpBasicInfo
 * @description fn Set Corp Basic Info 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSetCorpBasicInfo = async function (items) {
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        $c.util.getComponent('AKCKwd').setValue("");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        const isurcd = items.isurcd;
        const repisucd = items.repisucd;
        const repisusrtcd = items.repisusrtcd;
        const comabbr = items.comabbrv;
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", repisucd);
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repisusrtcd);
        $c.util.getComponent('AKCKwd').setValue(comabbr);
        await scwin.fnInit();
    }
};
